import openpyxl
from openpyxl.utils import get_column_letter

wb = openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
ws = wb['Data']

for r in range(19, 24):
    print(f"\nData row {r} non-empty cells:")
    for c in range(1, 27):
        v = ws.cell(row=r, column=c).value
        if v is not None and v != '':
            print(f"  {get_column_letter(c)}{r} = {v!r}")

# Find where years 2019-2023 appear in rows 1-60, cols 1-30
years = {2019,2020,2021,2022,2023}
found = []
for r in range(1, 61):
    for c in range(1, 31):
        v = ws.cell(row=r, column=c).value
        if v in years:
            found.append((v, r, c))

print('\nFound year headers in Data sheet:')
for v,r,c in sorted(found, key=lambda t:(t[1],t[2])):
    print(f"  {v} at {get_column_letter(c)}{r}")
